const responseJson = res.body;
// Check if the token exists in the response
if (responseJson && responseJson.accessToken) {
  // Create a temporary runtime variable (available for subsequent requests in the run)
  bru.setVar('accessToken', responseJson.accessToken);

  // Create or update an environment variable (specific to the selected environment)
  // Use { persist: true } if you want the value to be saved to the environment file
  bru.setEnvVar('accessToken', responseJson.accessToken);

  console.log('Access token stored successfully!');
} else {
  console.log('Access token not found in the response.');
}

